# --- tool + registry ---
def get_weather(city: str) -> str:
    return f"{city}: 18C, light rain"

REGISTRY = {"get_weather": get_weather}

# --- fake provider-agnostic client ---
class FakeClient:
    def __init__(self):
        self.calls = 0
    def chat(self, messages, tools=None, **kw):
        self.calls += 1
        if self.calls == 1:
            # reason: ask for a tool
            tc = [{"id": "c1", "name": "get_weather", "args": {"city": "Paris"}}]
            return type("R", (), {"content": None, "tool_calls": tc})()
        # second call: model answers with the observation in hand
        return type("R", (), {"content": "It is 18C and rainy in Paris.", "tool_calls": []})()

# --- the loop ---
def run_agent(client, goal, max_steps=5):
    messages = [{"role": "user", "content": goal}]
    for _ in range(max_steps):
        resp = client.chat(messages)              # 1. reason
        if not resp.tool_calls:                    # stop condition
            return resp.content
        for call in resp.tool_calls:               # 2. act
            result = REGISTRY[call["name"]](**call["args"])
            messages.append({"role": "tool",       # 3. observe
                             "tool_call_id": call["id"],
                             "content": str(result)})
    raise RuntimeError("hit step cap")

