def get_price(item: str) -> float:
    return {"widget": 4.0, "gadget": 6.0}[item]

def multiply(x: float, y: float) -> float:
    return x * y

REGISTRY = {"get_price": get_price, "multiply": multiply}

class ScriptedClient:
    """Emits a fixed sequence of tool calls, then a final answer."""
    def __init__(self, script):
        self.script = script
        self.i = 0
    def chat(self, messages, tools=None, **kw):
        step = self.script[self.i]
        self.i += 1
        return type("R", (), step)()

script = [
    {"content": None, "tool_calls": [{"id": "a", "name": "get_price", "args": {"item": "widget"}}]},
    {"content": None, "tool_calls": [{"id": "b", "name": "multiply", "args": {"x": 4.0, "y": 3}}]},
    {"content": "3 widgets cost $12.00.", "tool_calls": []},
]

def run_agent(client, goal, max_steps=6):
    messages = [{"role": "user", "content": goal}]
    for step in range(max_steps):
        resp = client.chat(messages)
        if not resp.tool_calls:
            print(f"[step {step}] final answer")
            return resp.content
        for call in resp.tool_calls:
            result = REGISTRY[call["name"]](**call["args"])
            print(f"[step {step}] {call['name']}{call['args']} -> {result}")
            messages.append({"role": "tool", "tool_call_id": call["id"], "content": str(result)})
    raise RuntimeError("agent hit step cap without finishing")

answer = run_agent(ScriptedClient(script), "Cost of 3 widgets?")
print(answer)

