registry = {"echo": echo}

class Client:
    def __init__(self):
        self.i = 0
        self.script = [
            {"content": None, "tool_calls": [{"id": "x1", "name": "echo", "args": {"text": "hi"}}]},
            {"content": "done: hi", "tool_calls": []},
        ]
    def chat(self, messages, **kw):
        step = self.script[self.i]
        self.i += 1
        return type("R", (), step)()

out = run_agent(Client(), "say hi", registry)
assert out == "done: hi", out

